import sqlite3;c=sqlite3.connect('canon.db')
def add(cat,o,f,r,h): c.execute("insert into canon(categorie,onderwerp,feit,status,reden,hangt_samen_met,ronde) values(?,?,?,'voorlopig',?,?,7)",(cat,o,f,r,h))
# nieuwe rituelen
N=[
('De Tweegelofte','Twee volwassenen (vrouwen onder elkaar, of vrouw en gewone man die zij bezit of vrijkoopt).','Binnenhof, onder getuigen van het moederhuis.','Vrijwillig; bindt niet exclusief (het geloof verbiedt exclusiviteit), maar belooft voorrang en terugkeer.','Ruil van een haarlok en een ring; samen baden; een nacht alleen; gelofte “ik keer altijd terug”.','Geen zaad-kracht; wel rang als paar in het moederhuis.','Hechting en liefde; Gezin en wonen'),
('Het Afscheid van de Uitverkorene','Vrouwen die door een gaven-man gezegend zijn, zijn huis, Moeders.','Tempel, als een gaven-man sterft, vlucht of zijn gave verliest.','Eenmalig; elke vrouw legt een gouden oorring terug.','Stoet in goud; elke vrouw spreekt een herinnering uit; de oorringen worden omgesmolten tot een beeld.','Rang blijft, kracht stopt; zijn lijn wordt in het register gesloten.','Gaven-mannen; Aeron-as'),
('De Verzoening','Twee rivalen (vrouwen of huizen).','Badhuis.','Op voorstel van een Moeder; heilig woord.','Elkaar wassen; gezamenlijke maaltijd; een gedeelde nacht of een gedeelde man; zout op de tong.','Herstel van rang; einde van vete.','Duel om een Man; Huizen'),
('Het Stille Kind','Moeder en moederhuis bij de dood van een kind.','Binnenhof.','Geen zaad, geen ontvangst gedurende 40 dagen.','Grijze sjerp; het belletje (bij een jongen) of de naam begraven onder de vijgenboom; zang.','Moeder wordt een tijd “gesloten”; huis rouwt mee.','Geboortelied; Gezondheid'),
('De Zilverwake','Vrouwen die geen kinderen meer krijgen (ouderdom).','Tempel.','Eenmaal, rond het 50e jaar.','Grijze sjerp wordt zilver; ze worden Moeder, Hoedster of raadsvrouw; de jongeren zalven haar.','Overgang naar gezag: zij leiden voortaan riten.','Orde; Cultuur'),
('De Halsbandoverdracht','Een gewone man, zijn oude en nieuwe eigenares, Registratrix.','Zaadbeurs of moederhuis.','Stil; de man mag een laatste nacht met wie hij wil (vaak de oude eigenares).','Laatste nacht; halsband wordt doorgeknipt en nieuwe omgedaan; registratie.','Geen kracht; behoud van zijn band met oude kinderen in het register.','Gewone mannen; Bram'),
('De Zegelnacht van het Volk','Iedereen (18+), jaarlijks.','Bij elke zegelsteen.','Publiek gevierd als dankfeest; in werkelijkheid de grootste voeding van de zegel.','Samen ontvangen bij de stenen; gezamenlijke zang; zegellicht vlamt.','Geen kracht (gaat naar de zegel); veel rang.','HET GEHEIM; Zegelvoeding'),
]
for n,w,p,r,s,e,h in N: add('Rituelen',n,f"Wie: {w} Plek: {p} Regels: {r} Stappen: {s} Effect: {e} Kink-schaal: {2 if n!='De Zegelnacht van het Volk' else 3}. Alle deelnemers 18+.",'Vult een gat in de levenscyclus of in het systeem (ronde 7).',h)
# systeem per ritueel: (meta, heersers, volk, taboe, verborgen, moment, band, wegval)
