for o,(m,he,v,t,vf,mo,b,w) in S.items():
  assert c.execute("select 1 from canon where onderwerp=? and categorie in ('Rituelen','Extreme rituelen')",(o,)).fetchone(),o
  add('Ritueel systeem',o,f"Metadoel: {m}. Heersers halen eruit: {he}. Volk haalt eruit/gelooft: {v}. Overschreden taboe: {t}. Verborgen functie (alleen de orde): {vf}. Moment: {mo}. Band: {b}. Als het wegvalt: {w}.",'Rituelen als systeem: macht, hechting, loyaliteit en geloof (Van Gennep, Durkheim).',o)
add('Ritueel systeem','Levenscyclus en kalender',"Levenscyclus: Geboortelied → (jongens: Jongenshof) → Wijding (18) → Pelgrimszalving/Reizigersgroet bij reizen → Ontvangst en Gunstnacht → Tweegelofte → Melkzegen na elke geboorte (Stille Kind bij verlies) → Duel en Verzoening bij rivaliteit → Boeterite, Tribunaal en Schandpodium bij misdaad → Zilverwake (±50) → Laatste Bed. Voor mannen: Wijding → Uitverkorene (Ontvangst, Gunstnacht, Afscheid van de Uitverkorene) of gewone man (Veiling, Melkrite, Kettingstoet, Halsbandoverdracht). Jaar: nieuwjaar Zegelnacht van het Volk; lente Lentenacht/Wijding; zomer Nacht der Duizend Lampen; oogst Oogstbed; droog seizoen Zwijgende Rit; winter Gletsjerproef en Nacht der Omkering (zonnewende); elke volle maan Maanzalving; maandelijks Veiling; geheim jaarlijks Zegelvoeding. Samenhang: Wijding opent alle riten; Ontvangst → Leegtewake; Duel → Verzoening; Tribunaal → Boeterite/Schandpodium. Ontbrekend nog: een rite voor zwangerschap zelf en een rite voor het vertrek van jongens naar het Jongenshof (niet-seksueel).",'Toont hoe rituelen op elkaar voortbouwen.','Rituelen; Extreme rituelen')
add('Ritueel systeem','Hechting en liefde',"Liefde ontstaat ondanks het systeem: tussen vrouwen in moederhuizen (Maanzalving, Tweegelofte, Laatste Bed), tussen vrouw en gaven-man (Gunstnacht, Overdracht, Stormontlading, Spiegelnacht), en tussen een gewone man en zijn eigenares of Hoedster (Melkrite, Halsbandwissel, Halsbandoverdracht). Het geloof laat liefde toe zolang ze niet exclusief wordt: trouw is voorrang, geen bezit. Bedreigend voor liefde: Veiling, Kettingstoet, Ontzegging en binding, Bloedverbinding (schijnliefde door verslaving). Echte liefde is daarom stil verzet; Liora en Aeron-as zijn er het voorbeeld van.",'Rogier: heersers halen er ook liefde uit.','Personages; Rituelen')
add('Ritueel systeem','Integratie van het geloof',"Elk ritueel verankert de leer in het lichaam: sjerpkleuren veranderen bij elke rite (wit bij de Wijding, rood ontvankelijk, goud gezegend, grijs rouw of boete, zilver ouderdom); oorringen tellen zegeningen; namen komen van het moederhuis en worden bij de Overdracht afgelegd; eten (mannenvoer, zout bij Verzoening) hoort bij riten; werk volgt de kalender (oogst = Oogstbed). Het zegellicht maakt het verhaal van Ysa zichtbaar en tastbaar bij elke ontvangst. Kostbare signalen (Ketenwake, Zevenvoudige Ontvangst) bewijzen geloof; gedeelde taboe-overschrijding maakt het volk medeplichtig en dus trouw. Rouw (Laatste Bed, Stille Kind) laat troost lopen via het geloof.",'Rituelen dragen het geloof over in lichaam en herinnering.','Religie; Cultuur')
W=[('Dankfeest of voeding','Zegelnacht van het Volk; HET GEHEIM','Het volk viert dank, terwijl zijn kracht wordt weggezogen. Als het uitlekt: opstand.','bron van verhalen','open'),
('Liefde tegen niet-exclusiviteit','Tweegelofte; Geloof','De orde laat liefde toe, maar exclusieve liefde (Liora–Aeron) is ketterij.','bron van verhalen','open'),
('Kalender en zaad-kracht','Kalender; Magie','Grote feesten (Duizend Lampen, Zegelnacht) voeden de zegel en geven dus weinig kracht; toch denkt het volk dat het krachtfeesten zijn. Oplossing: men voelt euforie (collectieve opwinding) in plaats van kracht.','mogelijke fout','voorstel'),
('Ontdekking van de verborgen functie','Ritueel systeem; Queeste','Als Liora bewijst wat de Zegelvoeding doet, verliest elk ritueel zijn legitimiteit: het einde van de queeste.','bron van verhalen','open'),
('Ventielen kunnen ontsporen','Rolwisseling; Zwijgende Rit','Riten die spanning afvoeren kunnen een opstand starten (Bram).','bron van verhalen','open')]
for x in W: c.execute('insert into wrijving(titel,delen_die_botsen,beschrijving,type,status) values(?,?,?,?,?)',x)
for q in [('Mag exclusieve liefde (Liora–Aeron) ketterij zijn, of laat de orde dat toe?','Bepaalt het conflict in de liefdeslijn.'),('Moet het volk de verborgen functie van de riten aan het eind ontdekken?','Bepaalt het einde.'),('Wil je een rite voor zwangerschap en voor het vertrek van jongens naar het Jongenshof (niet-seksueel)?','Vult de levenscyclus.')]:
  c.execute("insert into open_vraag(vraag,waarom_belangrijk,status) values(?,?,'open')",q)
c.execute("insert into logboek(datum,wat) values('2026-10-30','Ronde 7: ritueel systeem (45 rijen + 3 overzichten), 7 nieuwe rituelen, 5 wrijvingen, 3 open vragen.')");c.commit()
